// Get the Slack response from the previous node
const slack = $input.first().json;

// Get the Formstack data.
// Replace "Extract Formstack Data" with the actual name of your node.
const form = $("Validated Formstack Data").first().json;

// Current round robin index.
// Load this from a Data Store before this Code node.
const currentIndex = Number(form.currentIndex ?? 0);

// Slack User IDs
const USERS = {
  user1: "U0BD0QGKLRG",
  user2: "U0BD4FKB50C",
  user3: "U0BE4L71NBA",
};

// Routing
const ROUTES = {
  "Business Registration": [USERS.user1, USERS.user2, USERS.user3],

  "Virtual Office": [USERS.user1, USERS.user2, USERS.user3],

  Coworking: [USERS.user2, USERS.user3],
};

// Default routing
const DEFAULT_POOL = [USERS.user1, USERS.user2, USERS.user3];

// Get the matching pool
const pool = ROUTES[form.service] ?? DEFAULT_POOL;

// Pick assignee
const assignedUser = pool[currentIndex % pool.length];

// Calculate next index
const nextIndex = (currentIndex + 1) % pool.length;

return [
  {
    json: {
      // Slack values
      channel: slack.channel,
      thread_ts: slack.ts,

      // Assignment
      assignedUser,
      slackMention: `<@${assignedUser}>`,
      service: form.service,

      // Save this back to your Data Store
      currentIndex,
      nextIndex,
    },
  },
];

